#!/usr/bin/env node
/**
 * forge — PreToolUse hook: pre-approval-gate.cjs
 * Generated by forge (SPEC-083 P6 / SPEC-081). Zero dependencies, pure Node.
 * CommonJS with .cjs extension ON PURPOSE: installed projects may declare
 * "type": "module" in their root package.json, and a CJS .js file would crash
 * with ReferenceError before the circuit runs. .cjs is unambiguous everywhere.
 *
 * Forwards the tool call to the local approvals circuit (mingako daemon) using
 * the SPEC-081 §3 protocol:
 *
 *   1. POST /api/v1/approvals            → 201 {id}   (ApprovalRequest body)
 *   2. GET  /api/v1/approvals/:id/wait   → ApprovalResolution (long-poll)
 *
 * Discovery: ~/.forge/daemon.json only (env override FORGE_DAEMON_URL/
 * FORGE_DAEMON_TOKEN, loopback-only). FORGE_HOME is NOT consulted: for the
 * CLI it means the forge assets root, a different thing. The wire contract is
 * approval-request.schema.json / approval-resolution.schema.json in
 * @cristiancorreau/forge-schemas.
 *
 * Kind mapping (SPEC-081 §1): ExitPlanMode → 'plan', AskUserQuestion →
 * 'question', everything else → 'tool_use'. timeoutMs comes from
 * approvals.timeout_seconds in project.yaml (default 300, capped at 3600).
 *
 * Output (SPEC-081 §4.4): the structured PreToolUse JSON
 * {"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":
 * "allow"|"deny","permissionDecisionReason":"..."}} and exit 0. A resolution
 * with decision 'timeout' maps to DENY (SPEC-081 §1); decision 'answer'
 * travels as deny with the human answer in permissionDecisionReason.
 *
 * FAIL-OPEN by design: without daemon.json, with a corrupt file, an
 * unreachable/hung daemon or ANY unexpected error, the hook exits 0 silently.
 * The <2s fail-open budget covers discovery + POST (daemon unreachable); once
 * the daemon acknowledged the request (201), the hook waits for the human up
 * to timeoutMs + 5s and only then fails open.
 *
 * Security: the hook only ever connects to loopback (a poisoned
 * FORGE_DAEMON_URL pointing anywhere else is ignored) and the bearer token is
 * never written to stdout/stderr or logs.
 */
'use strict';

const fs = require('fs');
const path = require('path');
const os = require('os');
const http = require('http');

const DEBUG = !['', '0', 'false', 'False'].includes(process.env.DEBUG || '');
// Diagnostics go to stderr (never the token). Optional, silent by default.
const dbg = msg => DEBUG && process.stderr.write(`[forge-approval-gate] ${msg}\n`);

// Phase 1 (discovery + POST): the hook must never delay a tool call more than
// ~2s when the daemon is missing, dead or hung before acknowledging.
const POST_TIMEOUT_MS = 1500;
const FAIL_OPEN_BUDGET_MS = 2000;
// Phase 2 (human resolution): hard client timeout = timeoutMs + margin
// (SPEC-081: "timeout duro en el cliente HTTP del hook = timeoutMs + 5s").
const WAIT_MARGIN_MS = 5000;
const DEFAULT_TIMEOUT_SECONDS = 300;
const MAX_TIMEOUT_SECONDS = 3600;

const allow = why => { dbg(`fail-open/allow: ${why}`); process.exit(0); };

// Hard fail-open guard: whatever happens, exit 0 when the budget is spent.
// Re-armed to timeoutMs + margin once the daemon acknowledged the request.
let budgetTimer = setTimeout(() => allow('total budget exceeded'), FAIL_OPEN_BUDGET_MS);

process.on('uncaughtException', e => allow(`uncaught: ${e && e.message}`));
process.on('unhandledRejection', e => allow(`unhandled: ${e && e.message}`));

// ---------------------------------------------------------------------------
// Daemon discovery — ~/.forge/daemon.json (shape: daemon-discovery.schema.json)
// ---------------------------------------------------------------------------
const LOOPBACK_HOSTNAMES = new Set(['127.0.0.1', 'localhost', '::1', '[::1]']);

function discoverDaemon() {
  // Env override (useful for tests and non-default setups). LOOPBACK-ONLY:
  // the hook posts the full tool payload plus a bearer token, so a poisoned
  // FORGE_DAEMON_URL pointing to a remote host would exfiltrate both. Any
  // non-loopback hostname is ignored and the connection is forced to
  // 127.0.0.1; the port must be an explicit integer in 1..65535.
  const envUrl = process.env.FORGE_DAEMON_URL || '';
  if (envUrl) {
    try {
      const u = new URL(envUrl);
      if (!LOOPBACK_HOSTNAMES.has(u.hostname)) return null;
      const port = Number(u.port);
      if (!Number.isInteger(port) || port < 1 || port > 65535) return null;
      return { host: '127.0.0.1', port, token: process.env.FORGE_DAEMON_TOKEN || '' };
    } catch { return null; }
  }
  // Fixed location per daemon-discovery.schema.json / SPEC-081 §4.2. Never
  // FORGE_HOME: that variable is the CLI assets root, and honoring it here
  // would silently disable approvals for users who point it at their forge
  // root (fail-open hides the miss).
  const file = path.join(os.homedir(), '.forge', 'daemon.json');
  if (!fs.existsSync(file)) return null;
  let data;
  try { data = JSON.parse(fs.readFileSync(file, 'utf8')); } catch { return null; }
  if (!data || typeof data !== 'object') return null;
  const port = data.port;
  const token = data.token;
  if (!Number.isInteger(port) || port < 1 || port > 65535) return null;
  if (typeof token !== 'string' || token === '') return null;
  return { host: '127.0.0.1', port, token };
}

// ---------------------------------------------------------------------------
// approvals.timeout_seconds from project.yaml (SPEC-081: default 300, max
// 3600). Minimal line-based parse — the hook stays zero-dependency.
// ---------------------------------------------------------------------------
function readTimeoutMs(cwd) {
  let seconds = DEFAULT_TIMEOUT_SECONDS;
  try {
    const file = path.join(cwd, 'project.yaml');
    if (fs.existsSync(file)) {
      const text = fs.readFileSync(file, 'utf8');
      const block = text.match(/^approvals:[ \t]*\r?\n((?:[ \t]+[^\r\n]*\r?\n?)*)/m);
      const m = block && block[1].match(/^[ \t]+timeout_seconds:[ \t]*([0-9]+)[ \t]*$/m);
      if (m) seconds = parseInt(m[1], 10);
    }
  } catch { /* fail-open: default */ }
  if (!Number.isInteger(seconds) || seconds < 1) seconds = DEFAULT_TIMEOUT_SECONDS;
  if (seconds > MAX_TIMEOUT_SECONDS) seconds = MAX_TIMEOUT_SECONDS;
  return seconds * 1000;
}

// Kind mapping (SPEC-081 §1): plans and questions are first-class approvals.
function kindForTool(toolName) {
  if (toolName === 'ExitPlanMode') return 'plan';
  if (toolName === 'AskUserQuestion') return 'question';
  return 'tool_use';
}

// ---------------------------------------------------------------------------
// Structured PreToolUse output (SPEC-081 §4.4) — always exit 0; Claude Code
// reads permissionDecision from stdout JSON.
// ---------------------------------------------------------------------------
function emitDecision(permissionDecision, permissionDecisionReason) {
  clearTimeout(budgetTimer);
  process.stdout.write(JSON.stringify({
    hookSpecificOutput: {
      hookEventName: 'PreToolUse',
      permissionDecision,
      permissionDecisionReason,
    },
  }) + '\n');
  process.exit(0);
}

function handleResolution(resolution) {
  const decision = resolution.decision;
  if (decision === 'allow') {
    emitDecision('allow', 'Aprobado desde el circuito externo de aprobaciones (mingako).');
  }
  if (decision === 'deny') {
    const reason = typeof resolution.reason === 'string' && resolution.reason
      ? resolution.reason
      : 'Un humano denegó esta acción desde el circuito externo de aprobaciones (mingako).';
    emitDecision('deny', reason);
  }
  if (decision === 'timeout') {
    // SPEC-081 §1: decision 'timeout' always maps to DENY on the runtime side.
    emitDecision('deny',
      'Sin respuesta humana dentro del timeout del circuito de aprobaciones: denegado (SPEC-081).');
  }
  if (decision === 'answer') {
    // plan/question: the human answer travels in permissionDecisionReason
    // (deny) so the agent incorporates it (SPEC-081 §4.4).
    const a = (resolution.answer && typeof resolution.answer === 'object') ? resolution.answer : {};
    const parts = [];
    if (Array.isArray(a.optionIds) && a.optionIds.length > 0) parts.push(`opciones: ${a.optionIds.join(', ')}`);
    if (typeof a.text === 'string' && a.text) parts.push(a.text);
    emitDecision('deny',
      `Respuesta del humano desde el circuito de aprobaciones: ${parts.join(' — ') || 'sin detalle'}`);
  }
  // Unknown decision → permit (fail-open contract).
  allow(`decision desconocida: ${String(decision)}`);
}

// Minimal JSON-over-HTTP helper against the loopback daemon. Any transport or
// parse failure fails open; `onOk` receives the parsed 2xx body.
function daemonJson(daemon, options, body, timeoutMs, onOk) {
  const headers = {
    'content-type': 'application/json',
    'authorization': `Bearer ${daemon.token}`,
  };
  if (body !== null) headers['content-length'] = Buffer.byteLength(body);
  const req = http.request({
    host: daemon.host,
    port: daemon.port,
    timeout: timeoutMs,
    headers,
    ...options,
  }, res => {
    let out = '';
    res.setEncoding('utf8');
    res.on('data', chunk => { out += chunk; });
    res.on('error', () => allow('response error'));
    res.on('end', () => {
      if (res.statusCode < 200 || res.statusCode >= 300) allow(`status ${res.statusCode}`);
      let parsed;
      try { parsed = JSON.parse(out); } catch { allow('response parse error'); }
      if (!parsed || typeof parsed !== 'object') allow('response not an object');
      onOk(parsed);
    });
  });
  req.on('timeout', () => { req.destroy(); allow('request timeout'); });
  req.on('error', e => allow(`request error: ${e && e.code}`));
  if (body !== null) req.end(body); else req.end();
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------
let raw = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', chunk => { raw += chunk; });
process.stdin.on('error', () => allow('stdin error'));
process.stdin.on('end', () => {
  if (!raw.trim()) allow('empty stdin');

  let data;
  try { data = JSON.parse(raw); } catch { allow('stdin parse error'); }

  const toolName = data.tool_name || '';
  if (!toolName) allow('no tool_name');

  const daemon = discoverDaemon();
  if (!daemon) allow('no daemon discovered');

  const cwd = (typeof data.cwd === 'string' && data.cwd) ? data.cwd : process.cwd();
  const timeoutMs = readTimeoutMs(cwd);

  // ApprovalRequest wire body (approval-request.schema.json). The daemon
  // assigns id/createdAt and builds the card (SPEC-081 §3).
  const request = {
    kind: kindForTool(toolName),
    tool: toolName,
    sessionId: data.session_id || '',
    payload: data.tool_input || {},
    timeoutMs,
  };
  const body = JSON.stringify(request);

  // Phase 1 — POST /api/v1/approvals → 201 {id} (SPEC-081 §3).
  daemonJson(daemon, { path: '/api/v1/approvals', method: 'POST' }, body, POST_TIMEOUT_MS, created => {
    const id = created.id;
    if (typeof id !== 'string' || id === '') allow('POST sin id (daemon no conforme)');

    // Daemon alive and request acknowledged: re-arm the fail-open guard to
    // cover the human wait (timeoutMs + margin), not the 2s transport budget.
    clearTimeout(budgetTimer);
    budgetTimer = setTimeout(() => allow('wait budget exceeded'), timeoutMs + WAIT_MARGIN_MS);

    // Phase 2 — long-poll GET /api/v1/approvals/:id/wait → ApprovalResolution.
    daemonJson(daemon, {
      path: `/api/v1/approvals/${encodeURIComponent(id)}/wait?timeoutMs=${timeoutMs}`,
      method: 'GET',
    }, null, timeoutMs + WAIT_MARGIN_MS, resolution => handleResolution(resolution));
  });
});
